  async function loadReports(){var r=await getReportsFromApi(); if(r)return r; r=await getReportsFromFile(); if(r)return r; return [];}
  function statusLabel(t){if(!t)return ''; if(t.status==='CLOSED'&&t.retestResult==='PASS')return 'RETEST PASS / CLOSED'; if(t.status==='IN_REPAIR'&&t.retestResult==='FAIL')return 'RETEST FAIL / IN REPAIR'; return t.status||'';}
