  function dedupeTests(rows){var map={}; (rows||[]).forEach(function(r){var d=tsOf(r); var key=[serialOf(r), d?Math.round(d.getTime()/1000):String(r.timestamp||''), normResult(r), recipeOf(r), operatorOf(r)].join('|'); if(!map[key] || (stationOf(r)&&!stationOf(map[key]))) map[key]=r;}); return Object.keys(map).map(function(k){return map[k];}).sort(function(a,b){return (tsOf(a)?tsOf(a).getTime():0)-(tsOf(b)?tsOf(b).getTime():0);});}
  function testEventType(r,reps){var res=normResult(r); var t=tsOf(r); var time=t?t.getTime():0; var retest=reps.some(function(x){var req=ms(x.retestRequestedAt||x.updatedAt||x.createdAt); var end=ms(x.retestAt||x.closedAt||x.updatedAt); return req && time>=req-1000 && (!end || time<=end+60000);}); if(retest&&res==='PASS')return 'RETEST_PASS'; if(retest&&res==='FAIL')return 'RETEST_FAIL'; if(res==='PASS')return 'TEST_PASS'; if(res==='FAIL')return 'TEST_FAIL'; return 'TEST_'+res;}
  function buildTimeline(serial,tests,reps){var ev=[]; dedupeTests(tests).forEach(function(r){var d=tsOf(r); ev.push({ts:d?d.toISOString():'',ms:d?d.getTime():0,type:testEventType(r,reps),who:operatorOf(r),detail:'Ricetta '+(recipeOf(r)||'—')+' · Postazione '+(stationOf(r)||'—'),raw:r});}); reps.forEach(function(t){ev.push({ts:t.createdAt||'',ms:ms(t.createdAt),type:'REPAIR_OPEN',who:t.operator||'',detail:t.id+' · Difetto: '+(t.defect||'—')}); if(t.technician||t.defect||t.cause||t.correctiveAction||t.components){ev.push({ts:t.updatedAt||t.createdAt||'',ms:ms(t.updatedAt||t.createdAt),type:'REPAIR_ACTION',who:t.technician||'',detail:'Causa: '+(t.cause||'—')+' · Azione: '+(t.correctiveAction||'—')+' · Componenti: '+(t.components||'—')});} if(t.retestRequestedAt){ev.push({ts:t.retestRequestedAt,ms:ms(t.retestRequestedAt),type:'RETEST_REQUESTED',who:t.technician||t.operator||'',detail:t.id+' inviato a retest'});} if(t.retestResult==='PASS'){ev.push({ts:t.retestAt||t.closedAt||t.updatedAt||'',ms:ms(t.retestAt||t.closedAt||t.updatedAt),type:'RETEST_PASS',who:t.operator||'',detail:t.id+' retest PASS'});} if(t.retestResult==='FAIL'){ev.push({ts:t.retestAt||t.updatedAt||'',ms:ms(t.retestAt||t.updatedAt),type:'RETEST_FAIL',who:t.operator||'',detail:t.id+' retest FAIL, ritorna in riparazione'});} if(t.status==='CLOSED'){ev.push({ts:t.closedAt||t.updatedAt||'',ms:ms(t.closedAt||t.updatedAt),type:'REPAIR_CLOSED',who:t.technician||t.operator||'',detail:t.id+' chiuso'});} }); var unique={}; ev.forEach(function(e){var k=[Math.round((e.ms||0)/1000),e.type,e.detail].join('|'); unique[k]=e;}); return Object.keys(unique).map(function(k){return unique[k];}).sort(function(a,b){return (a.ms||0)-(b.ms||0);});}
  function timelineHtml(events){var rows=events.map(function(e){var badge=e.type.indexOf('FAIL')>=0?'fail':(e.type.indexOf('PASS')>=0||e.type.indexOf('CLOSED')>=0?'pass':'info'); return '<tr><td>'+esc(e.ts?fmt(new Date(e.ts)):'—')+'</td><td><span class="repair65c-event '+badge+'">'+esc(e.type)+'</span></td><td>'+esc(e.who||'—')+'</td><td>'+esc(e.detail||'')+'</td></tr>';}); return table(['Data/Ora','Evento','Operatore/Tecnico','Dettaglio'],rows);}
  function testsHtml(tests,reps){var rows=dedupeTests(tests).map(function(r){var type=testEventType(r,reps); return '<tr><td>'+esc(tsOf(r)?fmt(tsOf(r)):'—')+'</td><td><span class="repair65c-event '+(type.indexOf('FAIL')>=0?'fail':type.indexOf('PASS')>=0?'pass':'info')+'">'+esc(type)+'</span></td><td>'+esc(normResult(r))+'</td><td>'+esc(recipeOf(r)||'—')+'</td><td>'+esc(operatorOf(r)||'—')+'</td><td>'+esc(stationOf(r)||'—')+'</td></tr>';}); return table(['Data','Tipo Test','Esito','Ricetta','Operatore','Postazione'],rows);}
  function renderFullDossier(serial,tests,reps){var html='<div class="repair65c-dossier-full"><div class="repair65c-dossier-header"><div><h3>📋 Dossier tecnico scheda</h3><p>Seriale <b>'+esc(serial)+'</b> · Test deduplicati e ticket riparazione completi</p></div><button class="btn btn-primary" onclick="openRepairUnitCard65A(\''+esc(serial)+'\')">🔄 Aggiorna dossier</button></div><div class="repair65a-unit-grid"><div class="repair65a-unit-box"><span>Seriale</span><b>'+esc(serial)+'</b></div><div class="repair65a-unit-box"><span>Test registrati</span><b>'+dedupeTests(tests).length+'</b></div><div class="repair65a-unit-box"><span>Ticket dossier</span><b>'+reps.length+'</b></div><div class="repair65a-unit-box"><span>Allegati</span><b>'+reps.reduce(function(a,t){return a+((t.attachments||[]).length);},0)+'</b></div></div><h4>🧭 Timeline completa</h4>'+timelineHtml(buildTimeline(serial,tests,reps))+'<h4>🧪 Storico test / retest</h4>'+testsHtml(tests,reps)+'<h4>🛠 Dettaglio ticket riparazione</h4>'+(reps.map(ticketDetailBlock).join('')||'<div class="hint">Nessun ticket riparazione incluso nel dossier.</div>')+'</div>'; return html;}
  window.openRepairUnitCard65A=async function(serial,openFull){serial=String(serial||'').trim(); if(!serial){toast('Seriale mancante','warning');return;} var reports=await loadReports(); var tests=reports.filter(function(r){return serialOf(r)===serial;}); var reps=tickets().filter(function(t){return t.serial===serial && t.includeInDossier!==false;}).sort(function(a,b){return ms(a.createdAt)-ms(b.createdAt);}); var box=$('repair65a-unit-card'); if(box)box.innerHTML=renderFullDossier(serial,tests,reps); if(openFull!==false){try{if(typeof window.showTab==='function')window.showTab('unit-card-tab',null); setTimeout(function(){var input=$('unit-serial-input'); if(input)input.value=serial; if(typeof window.loadUnitGenealogy410E==='function')window.loadUnitGenealogy410E(); var full=$('unit-card-tab'); if(full){var panel=$('repair65c-unit-dossier'); if(!panel){panel=document.createElement('section'); panel.id='repair65c-unit-dossier'; panel.className='panel repair65a-panel repair65c-dossier-panel'; full.appendChild(panel);} panel.innerHTML=renderFullDossier(serial,tests,reps);}},180);}catch(e){console.warn('[6.5C_FIX1] open dossier failed',e);}}
  };
