  window.openRepairUnitCard65A=async function(serial,openFull){serial=String(serial||'').trim(); if(!serial){toast('Seriale mancante','warning');return;} const all=await loadReports(); const tests=all.filter(r=>serialOf(r)===serial); const reps=repsForDossier(serial); const html=dossierHtml(serial,tests,reps); const local=$('repair65a-unit-card'); if(local)local.innerHTML=html; if(openFull!==false){try{if(typeof window.showTab==='function')window.showTab('unit-card-tab',null); setTimeout(()=>{const input=$('unit-serial-input'); if(input)input.value=serial; if(typeof window.loadUnitGenealogy410E==='function')window.loadUnitGenealogy410E(); setTimeout(()=>{const full=$('unit-card-tab'); if(full){let panel=$('repair65c-unit-dossier'); if(!panel){panel=document.createElement('section'); panel.id='repair65c-unit-dossier'; panel.className='panel repair65a-panel repair65c-dossier-panel'; full.appendChild(panel);} panel.innerHTML=html;} cleanupLegacyDuplicates();},300);},100);}catch(e){console.warn('[6.5C_FIX5] open dossier failed',e);}}};
