  window.addRepairAction65C3=function(id){const t=getTicket(id); if(!t)return; migrateTicket(t); t.repairActions.push({id:'INT-'+String(t.repairActions.length+1).padStart(3,'0'),createdAt:now(),technician:(window.currentUser&&(window.currentUser.username||window.currentUser.name))||'Admin',defect:'',cause:'',correctiveAction:'',components:'',notes:'',attachments:[]}); t.status='IN_REPAIR'; t.updatedAt=now(); saveTicket(t); log(t,'REPAIR_ACTION_NEW',{count:t.repairActions.length}); toast('Nuovo intervento aggiunto al ticket '+id,'success'); window.openRepairTicketsForSerial65C4(t.serial);};
