  window.checkRepairRetestResults65C=async function(silent){const reports=await loadReports(); const rows=tickets(); let changed=false; rows.filter(t=>t.status==='RETEST').forEach(t=>{const from=ms(t.retestRequestedAt||t.updatedAt||t.createdAt); const tests=reports.filter(r=>serialOf(r)===t.serial && (tsOf(r)?.getTime()||0)>=from-1000).sort((a,b)=>(tsOf(b)?.getTime()||0)-(tsOf(a)?.getTime()||0)); const latest=tests[0]; if(latest){const res=resultOf(latest); if(res==='PASS'||res==='FAIL'){migrateTicket(t); t.retestResult=res; t.retestAt=latest.timestamp||latest.created_at||now(); t.updatedAt=now(); if(res==='PASS'){t.status='CLOSED'; t.closedAt=now();} else {t.status='IN_REPAIR'; const last=t.repairActions[t.repairActions.length-1]||{}; const hasContent=!!(last.defect||last.cause||last.correctiveAction||last.components||last.notes); if(hasContent){t.repairActions.push({id:'INT-'+String(t.repairActions.length+1).padStart(3,'0'),createdAt:now(),technician:'',defect:'',cause:'',correctiveAction:'',components:'',notes:'',attachments:[]});}}
        changed=true; log(t,'RETEST_'+res+'_AUTO',{serial:t.serial,recipe:recipeOf(latest),nextAction:t.repairActions.length});}}}); if(changed){saveTickets(rows); toast('Risultati retest aggiornati nei ticket','success'); if(window.refreshRepairCenter65A)window.refreshRepairCenter65A();} else if(!silent) toast('Nessun nuovo risultato retest trovato','info');};
