  function read(k,d){try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d));}catch(_e){return d;}}
  function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){console.warn('[6.5C_FIX6] save failed',e);}}
